{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2171-07-29 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I'm Dr. Lee, one of your surgical team members. You were admitted this morning because of recurrent low blood sugar episodes, especially after your gastric bypass. We’re planning to place a gastrostomy tube today to help manage that."
    },
    {
      "turn_number": 2,
      "time": "2171-07-29 08:02:00",
      "speaker": "Patient",
      "text": "Hi, yes, I’ve been having those episodes more often. Will the tube help stop the lows?"
    },
    {
      "turn_number": 3,
      "time": "2171-07-29 08:04:00",
      "speaker": "Doctor",
      "text": "We hope so. The idea is to test whether feeding directly into the stomach helps stabilize your blood sugar. If it does, it might support considering a reversal of your bypass later."
    },
    {
      "turn_number": 4,
      "time": "2171-07-29 08:06:00",
      "speaker": "Patient",
      "text": "Oh, I didn’t know that was an option. Is the procedure safe?"
    },
    {
      "turn_number": 5,
      "time": "2171-07-29 08:08:00",
      "speaker": "Doctor",
      "text": "It’s generally safe, but like any surgery, there are risks. We started laparoscopically, but had to convert to open due to some scar tissue. We placed the tube and repaired a small colotomy we found. You’re stable now."
    },
    {
      "turn_number": 6,
      "time": "2171-07-29 08:10:00",
      "speaker": "Patient",
      "text": "I remember waking up in the recovery room. My belly feels sore, but I’m alert."
    },
    {
      "turn_number": 7,
      "time": "2171-07-29 08:12:00",
      "speaker": "Doctor",
      "text": "That’s expected. You’re on a PCA pump for pain with hydromorphone. We’ll switch to oral meds soon. You’re doing well neurologically and breathing fine."
    },
    {
      "turn_number": 8,
      "time": "2171-07-29 14:00:00",
      "speaker": "Doctor",
      "text": "Just checking in. Your labs are stable. Blood sugar was 112 this morning, which is good. We’ll keep monitoring it closely."
    },
    {
      "turn_number": 9,
      "time": "2171-07-29 14:02:00",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried about crashing again. Can I eat anything yet?"
    },
    {
      "turn_number": 10,
      "time": "2171-07-29 14:04:00",
      "speaker": "Doctor",
      "text": "Not yet. We’re starting you on clear liquids tomorrow. Your stomach and bowels need time to wake up after surgery."
    },
    {
      "turn_number": 11,
      "time": "2171-07-30 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re on a Stage 5 bariatric diet today—soft foods. Try small bites and chew well."
    },
    {
      "turn_number": 12,
      "time": "2171-07-30 09:02:00",
      "speaker": "Patient",
      "text": "Okay, I’ll try. My belly feels a little bloated though."
    },
    {
      "turn_number": 13,
      "time": "2171-07-30 09:04:00",
      "speaker": "Doctor",
      "text": "We noticed that. We’ll get an X-ray to check for ileus—when the bowels slow down after surgery. It’s common and usually temporary."
    },
    {
      "turn_number": 14,
      "time": "2171-07-31 10:00:00",
      "speaker": "Doctor",
      "text": "The X-ray shows post-op ileus. There’s no movement of contrast through your bowels. We’ll hold oral intake for now."
    },
    {
      "turn_number": 15,
      "time": "2171-07-31 10:02:00",
      "speaker": "Patient",
      "text": "So I can’t eat anything? How long will this last?"
    },
    {
      "turn_number": 16,
      "time": "2171-07-31 10:04:00",
      "speaker": "Doctor",
      "text": "It varies. We’ll encourage walking and use of the incentive spirometer. Most people improve in a few days. We’ll repeat the X-ray to monitor."
    },
    {
      "turn_number": 17,
      "time": "2171-07-31 16:30:00",
      "speaker": "Doctor",
      "text": "The repeat X-ray shows no change yet. We’re still seeing distention. But no free air, so no leak. That’s reassuring."
    },
    {
      "turn_number": 18,
      "time": "2171-07-31 16:32:00",
      "speaker": "Patient",
      "text": "I haven’t passed gas much. Is that part of it?"
    },
    {
      "turn_number": 19,
      "time": "2171-07-31 16:34:00",
      "speaker": "Doctor",
      "text": "Yes, reduced gas and bowel movements are typical with ileus. We gave a suppository, but it didn’t work. We’ll keep supporting you and wait."
    },
    {
      "turn_number": 20,
      "time": "2171-08-01 09:00:00",
      "speaker": "Doctor",
      "text": "Good news—your abdomen is less distended this morning. You passed gas and had a small bowel movement."
    },
    {
      "turn_number": 21,
      "time": "2171-08-01 09:02:00",
      "speaker": "Patient",
      "text": "Yes, I feel a bit better. Does that mean I can eat again?"
    },
    {
      "turn_number": 22,
      "time": "2171-08-01 09:04:00",
      "speaker": "Doctor",
      "text": "We’ll hold off on oral intake for now. But we’re planning to start tube feedings tomorrow. That’s the goal of the G-tube."
    },
    {
      "turn_number": 23,
      "time": "2171-08-01 09:06:00",
      "speaker": "Patient",
      "text": "Oh, right. How does that work?"
    },
    {
      "turn_number": 24,
      "time": "2171-08-01 09:08:00",
      "speaker": "Doctor",
      "text": "We’ll connect a feeding bag to your tube. The formula is high-protein, moderate-carb. It runs slowly through a pump, 24/7."
    },
    {
      "turn_number": 25,
      "time": "2171-08-02 10:00:00",
      "speaker": "Doctor",
      "text": "We’re starting your tube feedings today at a low rate. We’ll increase it gradually."
    },
    {
      "turn_number": 26,
      "time": "2171-08-02 10:02:00",
      "speaker": "Patient",
      "text": "Okay. Should I still take my diabetes meds?"
    },
    {
      "turn_number": 27,
      "time": "2171-08-02 10:04:00",
      "speaker": "Doctor",
      "text": "Yes, continue acarbose and pramlintide with meals. We’re monitoring your blood sugar every few hours to make sure it stays stable."
    },
    {
      "turn_number": 28,
      "time": "2171-08-02 14:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Blood sugars are staying between 100 and 130. No hypoglycemia. We’ll keep advancing the feeding rate."
    },
    {
      "turn_number": 29,
      "time": "2171-08-02 14:02:00",
      "speaker": "Patient",
      "text": "That’s great. I haven’t felt shaky or dizzy at all today."
    },
    {
      "turn_number": 30,
      "time": "2171-08-03 09:00:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. White count is a bit high, but that’s expected after surgery. No signs of infection."
    },
    {
      "turn_number": 31,
      "time": "2171-08-03 09:02:00",
      "speaker": "Patient",
      "text": "I’ve been walking a little more each day. My pain is better too."
    },
    {
      "turn_number": 32,
      "time": "2171-08-03 09:04:00",
      "speaker": "Doctor",
      "text": "Excellent. You’re on oral oxycodone now, and we’ll taper that soon. You’re also on omeprazole to protect your stomach."
    },
    {
      "turn_number": 33,
      "time": "2171-08-03 09:06:00",
      "speaker": "Patient",
      "text": "I remember I was on pantoprazole before. Why the switch?"
    },
    {
      "turn_number": 34,
      "time": "2171-08-03 09:08:00",
      "speaker": "Doctor",
      "text": "Omeprazole is similar and works well with your other meds. We’ll keep it for now to prevent ulcers, especially with your history."
    },
    {
      "turn_number": 35,
      "time": "2171-08-04 08:00:00",
      "speaker": "Doctor",
      "text": "You’re tolerating full tube feedings. Blood sugars remain stable. We’re planning to discharge tomorrow."
    },
    {
      "turn_number": 36,
      "time": "2171-08-04 08:02:00",
      "speaker": "Patient",
      "text": "That’s good. How do I manage the tube at home?"
    },
    {
      "turn_number": 37,
      "time": "2171-08-04 08:04:00",
      "speaker": "Doctor",
      "text": "You’ll keep the feedings running 24/7. Flush the tube with 100 mL water every 8 hours. We’ll send a nurse to help you at home."
    },
    {
      "turn_number": 38,
      "time": "2171-08-04 08:06:00",
      "speaker": "Patient",
      "text": "What if I have problems with the tube?"
    },
    {
      "turn_number": 39,
      "time": "2171-08-04 08:08:00",
      "speaker": "Doctor",
      "text": "Call us if you can’t flush it, if there’s leakage, or if you have nausea, vomiting, or distention. Also check residuals before feeding—if more than 50 mL, stop and call."
    },
    {
      "turn_number": 40,
      "time": "2171-08-04 08:10:00",
      "speaker": "Patient",
      "text": "And my blood sugar? Should I check it more often?"
    },
    {
      "turn_number": 41,
      "time": "2171-08-04 08:12:00",
      "speaker": "Doctor",
      "text": "Yes—before and after meals, at bedtime, and if you feel shaky. We want to see if the tube feedings are helping prevent lows."
    },
    {
      "turn_number": 42,
      "time": "2171-08-04 08:14:00",
      "speaker": "Patient",
      "text": "Makes sense. What about my other meds?"
    },
    {
      "turn_number": 43,
      "time": "2171-08-04 08:16:00",
      "speaker": "Doctor",
      "text": "Resume all your home meds except we’ve added docusate and bisacodyl to help prevent constipation from the pain meds and tube feedings."
    },
    {
      "turn_number": 44,
      "time": "2171-08-04 08:18:00",
      "speaker": "Patient",
      "text": "Okay, I’ll take those. When do I follow up?"
    },
    {
      "turn_number": 45,
      "time": "2171-08-04 08:20:00",
      "speaker": "Doctor",
      "text": "You’ll see Dr. ___ in two weeks. They’ll evaluate your response to the tube and discuss next steps, possibly reversal surgery."
    },
    {
      "turn_number": 46,
      "time": "2171-08-04 08:22:00",
      "speaker": "Patient",
      "text": "I’m hopeful this helps. I’m tired of living in fear of passing out."
    },
    {
      "turn_number": 47,
      "time": "2171-08-04 08:24:00",
      "speaker": "Doctor",
      "text": "We’re hopeful too. This is a big step. You’ve done really well—ambulating, no fever, pain controlled."
    },
    {
      "turn_number": 48,
      "time": "2171-08-05 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your final check—vitals are stable, wound looks clean, you’re passing gas, and feedings are going well."
    },
    {
      "turn_number": 49,
      "time": "2171-08-05 07:02:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. A little nervous, but ready."
    },
    {
      "turn_number": 50,
      "time": "2171-08-05 07:04:00",
      "speaker": "Doctor",
      "text": "We’ll send all instructions with you. Call if you have fever over 101.5, chest pain, vomiting, or tube issues."
    },
    {
      "turn_number": 51,
      "time": "2171-08-05 07:06:00",
      "speaker": "Patient",
      "text": "And if my blood sugar drops?"
    },
    {
      "turn_number": 52,
      "time": "2171-08-05 07:08:00",
      "speaker": "Doctor",
      "text": "Check it immediately. If it’s low, stop the tube feeding and call us. We may need to adjust the rate or formula."
    },
    {
      "turn_number": 53,
      "time": "2171-08-05 07:10:00",
      "speaker": "Patient",
      "text": "Got it. Thank you for explaining everything so clearly."
    },
    {
      "turn_number": 54,
      "time": "2171-08-05 07:12:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. You handled this surgery and recovery really well. We’re discharging you home with visiting nurse support."
    },
    {
      "turn_number": 55,
      "time": "2171-08-05 07:14:00",
      "speaker": "Patient",
      "text": "I’ll rest, walk daily, and follow the plan."
    },
    {
      "turn_number": 56,
      "time": "2171-08-05 07:16:00",
      "speaker": "Doctor",
      "text": "Perfect. Keep up the good work. We’ll see you in follow-up."
    },
    {
      "turn_number": 57,
      "time": "2171-08-05 09:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before discharge. Any new pain or concerns?"
    },
    {
      "turn_number": 58,
      "time": "2171-08-05 09:02:00",
      "speaker": "Patient",
      "text": "No, just a little sore at the incision, but it’s manageable."
    },
    {
      "turn_number": 59,
      "time": "2171-08-05 09:04:00",
      "speaker": "Doctor",
      "text": "That’s normal. Keep using the oral pain med as needed. Avoid heavy lifting for a few weeks."
    },
    {
      "turn_number": 60,
      "time": "2171-08-05 09:06:00",
      "speaker": "Patient",
      "text": "Will do. I’ll have my husband help with chores."
    },
    {
      "turn_number": 61,
      "time": "2171-08-05 09:08:00",
      "speaker": "Doctor",
      "text": "Good plan. And remember—flush the tube every 8 hours, even if not feeding."
    },
    {
      "turn_number": 62,
      "time": "2171-08-05 09:10:00",
      "speaker": "Patient",
      "text": "Yes, 100 mL of water. I’ve been practicing with the nurse."
    },
    {
      "turn_number": 63,
      "time": "2171-08-05 09:12:00",
      "speaker": "Doctor",
      "text": "Excellent. You’re all set. We’ll call you tomorrow to check in."
    },
    {
      "turn_number": 64,
      "time": "2171-08-05 09:14:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I really appreciate your care."
    },
    {
      "turn_number": 65,
      "time": "2171-08-05 09:16:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Take care, and we’ll talk soon."
    }
  ],
  "summary": {
    "admission_start": "2171-07-29 07:15:00",
    "admission_end": "2171-08-05 14:54:00",
    "summary_paragraph": "The patient was admitted for medically refractory hypoglycemia following Roux-en-Y gastric bypass, with the goal of placing a gastrostomy tube to evaluate whether direct stomach feeding could stabilize blood sugar and inform potential surgical reversal. She underwent a laparoscopic procedure converted to open for gastrostomy tube placement and repair of a colotomy. Postoperatively, she developed a transient paralytic ileus, managed conservatively with bowel rest and supportive care. By hospital day 4, she began passing gas and having bowel movements, allowing initiation of continuous enteral nutrition via the G-tube, which she tolerated well with stable blood glucose levels. Pain was controlled with a transition from IV to oral analgesia, and she remained afebrile and hemodynamically stable. She was discharged home on full enteral feeding, with instructions on tube care, medication management, and close outpatient follow-up to assess long-term metabolic response.",
    "problems": [
      "Other complications of other bariatric procedure",
      "Paralytic ileus",
      "Other specified hypoglycemia",
      "Esophageal reflux",
      "Laparoscopic surgical procedure converted to open procedure",
      "Bariatric surgery status",
      "Other chronic nonalcoholic liver disease",
      "Other digestive system complications",
      "Surgical operation with anastomosis, bypass, or graft, with natural or artificial tissues used as implant causing abnormal patient reaction, or later complication, without mention of misadventure at time of operation"
    ]
  }
}
